public class SortingStrategies {
    public static void countingSort(int[] arr, int maxValue) {
        int[] count = new int[maxValue + 1];
        for (int num : arr) {
            count[num]++;
        }
        int index = 0;
        for (int i = 0; i <= maxValue; i++) {
            while (count[i] > 0) {
                arr[index++] = i;
                count[i]--;
            }
        }
    }

    public static void main(String[] args) {
        int[] data = {4, 2, 2, 8, 3, 3, 1};
        countingSort(data, 8);
    }
}
